// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 sequenceNumber_,
        bytes32 batcherHash_,
        uint256 l1FeeOverhead_,
        uint256 l1FeeScalar_
    ) public {
        // No narrowing: full domain of the block values is admissible.
        // The only account allowed by the require is c's own depositorAccount,
        // read from the public getter (address(0) initially).
        address depositor = c.depositorAccount();
        vm.prank(depositor);
        c.setL1BlockValues(
            number_,
            timestamp_,
            basefee_,
            hash_,
            sequenceNumber_,
            batcherHash_,
            l1FeeOverhead_,
            l1FeeScalar_
        );
        // General rule: the setter never writes any L1 block state, so the
        // public basefee getter must remain at its initial value 0 for ALL
        // admissible inputs. The mutant stores _basefee, so any fuzzed input
        // with basefee_ != 0 violates it.
        assertTrue(c.basefee() == 0);
    }
}
